API Gateway / Anti-Corruption Layer (ACL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_acl, "API Gateway / Anti-Corruption Layer (ACL)") {
    Component(REST_API_Router, "REST API Router", "Custom microservices on Azure", "Handles incoming HTTPS/REST traffic from customers and brokers submitting claims online.")
    Component(Transformation_Engine, "Transformation Engine", "Custom microservices on Azure", "Decouples modern domain models from rigid legacy mainframe contracts using an adapter pattern.")
    Component(Cache_Manager, "Cache Manager", "Azure Redis Cache", "Executes read-through and write-behind caching to meet sub-second response SLAs.")
    Component(Message_Publisher, "Message Publisher", "Azure Service Bus", "Dispatches asynchronous event messaging and queueing for background processing.")
}

Rel(REST_API_Router, Transformation_Engine, "Routes requests for contract translation and validation", "")
Rel(Transformation_Engine, Cache_Manager, "Reads and writes cached claim data via TCP/Redis Protocol", "TCP / Redis Protocol")
Rel(Transformation_Engine, Message_Publisher, "Sends asynchronous events via AMQP/HTTPS", "AMQP / HTTPS")

@enduml

Event Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Event_Broker", "Event Broker") {
    Component("Message Ingestion Handler", "Message Ingestion Handler", "Azure Service Bus Topic Listener", "Receives asynchronous event messages from the API Gateway and BFF applications for the strangler migration.")
    Component("Claim Check Offloader", "Claim Check Offloader", "Azure Service Bus Middleware", "Offloads large payloads to Azure Blob Storage to bypass broker size limits.")
    Component("Dead-Letter Monitor", "Dead-Letter Monitor", "Azure Service Bus Dead-Letter Queue", "Monitors and captures failed messages and poisoned events to enforce reliability patterns and data consistency.")
}

Rel("Message Ingestion Handler", "Claim Check Offloader", "Routes large payloads for external storage via Claim Check pattern", "")
Rel("Message Ingestion Handler", "Dead-Letter Monitor", "Forwards failed or invalid messages", "")

@enduml

Caching / State Store.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(caching_state_store, "Caching / State Store") {
    Component(Cache_Aside_Read_Manager, "Cache-Aside Read Manager", "Azure Redis Cache / Node.js", "Manages low-latency read models, ephemeral session state, and cache population to meet sub-2-second UI performance targets.")
    Component(Idempotency_Stampede_Prevention_Module, "Idempotency & Stampede Prevention Module", "Azure Redis Cache / Lua Scripting", "Prevents cache stampedes and guarantees operation idempotency during concurrent claim submissions.")
}

Rel(Cache_Aside_Read_Manager, Idempotency_Stampede_Prevention_Module, "Validates concurrent requests and state consistency", "Redis Protocol")

@enduml

Backend-for-Frontend (BFF).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(bff, "Backend-for-Frontend (BFF)") {
    Component(Adjuster_Web_Application_Handler, "Adjuster Web Application Handler", "Azure Web Applications / Node.js", "Orchestrates interactions for the adjuster web application and exposes endpoints for client consumption.")
    Component(Orchestration___Data_Retrieval_Handler, "Orchestration & Data Retrieval Handler", "Azure Web Applications / REST / gRPC", "Manages internal orchestration and data retrieval interacting with the API Gateway and ACL.")
    Component(Caching___State_Manager, "Caching & State Manager", "Azure Redis Cache / TCP", "Externalizes session state and caches pre-aggregated read models for low-latency responses.")
    Component(Event_Driven_Migration_Publisher, "Event-Driven Migration Publisher", "Azure Service Bus / AMQP", "Handles asynchronous event-driven migration tasks and messaging.")
}

Rel(Adjuster_Web_Application_Handler, Orchestration___Data_Retrieval_Handler, "Delegates requests for internal orchestration and data retrieval", "HTTPS / gRPC")
Rel(Orchestration___Data_Retrieval_Handler, Caching___State_Manager, "Reads and writes low-latency read models and session state", "TCP / Redis Protocol")
Rel(Orchestration___Data_Retrieval_Handler, Event_Driven_Migration_Publisher, "Dispatches asynchronous events for migration", "AMQP / MQTT")

@enduml

